// Variant 3

(() => {
	const iter = MAPv3([1,3,5], 0, function*(x, acc) {
		yield 2*x
		return acc + x
	})

	return equal(arrayAndAccumFrom(iter), [
		[2, 6, 10],
		9
		])
}
	)();

